<script setup>
import { computed, onMounted, ref } from 'vue'
import AppTabBar from '../components/AppTabBar.vue'
import { createQuickMeeting, deleteMeeting, endMeeting, getMeetingDetail, getMeetings, joinMeeting, organizeMeeting, reserveMeeting, startMeeting } from '../api/meetings'

const meetings=ref([]),selected=ref(null),loading=ref(true),busy=ref(''),error=ref('')
const mode=ref('quick'),showForm=ref(false)
const form=ref({title:'',roomCode:'',scheduledStartTime:'',scheduledEndTime:''})
const rows=(response)=>response?.data?.records||response?.data?.content||response?.data||[]
const statusLabel=(value)=>({active:'进行中',idle:'待开始',ended:'已结束',reserved:'已预约'}[value]||value||'待开始')
const selectedId=computed(()=>selected.value?.sessionId||selected.value?.id)
async function load(){loading.value=true;try{meetings.value=rows(await getMeetings({pageNum:1,pageSize:50}))}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function open(item){try{const r=await getMeetingDetail(item.sessionId||item.id);selected.value=r.data||r}catch(cause){error.value=cause.message}}
async function submit(){
  busy.value='create';try{
    if(mode.value==='join')await joinMeeting({roomCode:form.value.roomCode})
    else if(mode.value==='reserve')await reserveMeeting({title:form.value.title,scheduledStartTime:form.value.scheduledStartTime,scheduledEndTime:form.value.scheduledEndTime})
    else await createQuickMeeting({title:form.value.title||'快速会议',participants:[]})
    showForm.value=false;form.value={title:'',roomCode:'',scheduledStartTime:'',scheduledEndTime:''};await load()
  }catch(cause){error.value=cause.message}finally{busy.value=''}
}
async function action(name){if(!selectedId.value)return;busy.value=name;try{if(name==='start')await startMeeting(selectedId.value);if(name==='end')await endMeeting(selectedId.value);if(name==='organize')await organizeMeeting(selectedId.value);if(name==='delete')await deleteMeeting(selectedId.value);selected.value=null;await load()}catch(cause){error.value=cause.message}finally{busy.value=''}}
function openForm(value){mode.value=value;showForm.value=true}
onMounted(load)
</script>
<template><div class="feature-page"><AppTabBar/><main class="feature-container"><header class="feature-heading"><div><h1>会议工作台</h1><p>发起、预约、加入并整理校园会议</p></div><div class="feature-actions"><button class="feature-button" @click="openForm('join')">加入会议</button><button class="feature-button" @click="openForm('reserve')">预约会议</button><button class="feature-button feature-button--primary" @click="openForm('quick')">快速会议</button></div></header><div v-if="error" class="feature-error">{{error}}</div><div class="meeting-layout"><section class="feature-card feature-section"><div class="feature-section__head"><h2>会议列表</h2><span>{{meetings.length}} 场</span></div><div v-if="loading" class="feature-empty">正在加载会议…</div><div v-else-if="!meetings.length" class="feature-empty">暂无会议</div><div class="feature-list"><button v-for="item in meetings" :key="item.sessionId||item.id" class="feature-row meeting-row" @click="open(item)"><div class="meeting-date"><strong>{{new Date(item.scheduledStartTime||item.startTime||item.createTime).getDate()||'—'}}</strong><span>日</span></div><div class="feature-row__copy"><strong>{{item.title||'未命名会议'}}</strong><span>会议号 {{item.roomCode||'—'}} · {{item.scheduledStartTime||item.startTime||'时间待定'}}</span></div><span :class="`feature-status feature-status--${item.status==='ended'?'completed':'learning'}`">{{statusLabel(item.status)}}</span></button></div></section><aside class="feature-card feature-section meeting-detail"><div class="feature-section__head"><h2>会议详情</h2></div><div v-if="!selected" class="feature-empty">选择一场会议查看详情</div><template v-else><h3>{{selected.title}}</h3><dl><div><dt>会议号</dt><dd>{{selected.roomCode||'—'}}</dd></div><div><dt>状态</dt><dd>{{statusLabel(selected.status)}}</dd></div><div><dt>开始时间</dt><dd>{{selected.scheduledStartTime||selected.startTime||'—'}}</dd></div><div><dt>参会人数</dt><dd>{{selected.participants?.length??'—'}}</dd></div></dl><div class="detail-actions"><button class="feature-button feature-button--primary" @click="action('start')">开始</button><button class="feature-button" @click="action('end')">结束</button><button class="feature-button" @click="action('organize')">智能整理</button><button class="feature-button feature-button--danger" @click="action('delete')">删除</button></div></template></aside></div></main><div v-if="showForm" class="feature-modal-mask" @click.self="showForm=false"><form class="feature-modal feature-form" @submit.prevent="submit"><div class="feature-modal__head"><h2>{{mode==='join'?'加入会议':mode==='reserve'?'预约会议':'快速会议'}}</h2><button type="button" class="feature-modal__close" @click="showForm=false">×</button></div><label v-if="mode==='join'">会议号<input v-model="form.roomCode" class="feature-input" required/></label><template v-else><label>会议主题<input v-model="form.title" class="feature-input" required/></label><template v-if="mode==='reserve'"><label>开始时间<input v-model="form.scheduledStartTime" class="feature-input" type="datetime-local" required/></label><label>结束时间<input v-model="form.scheduledEndTime" class="feature-input" type="datetime-local" required/></label></template></template><button class="feature-button feature-button--primary" :disabled="busy==='create'">确认</button></form></div></div></template>
<style scoped>
.meeting-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:18px}.feature-section__head>span{color:#718096}.meeting-row{width:100%;text-align:left}.meeting-date{display:grid;place-items:center;width:48px;height:48px;border-radius:8px;color:#315f8c;background:#eaf1f6}.meeting-date strong,.meeting-date span{display:block}.meeting-date span{font-size:10px}.meeting-row .feature-row__copy{flex:1}.meeting-detail{height:fit-content}.meeting-detail h3{font-size:22px}.meeting-detail dl{border-block:1px solid #e6ebf0}.meeting-detail dl div{display:flex;padding:12px 0}.meeting-detail dt{width:85px;color:#83909e}.meeting-detail dd{margin:0;color:#344a60}.detail-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:20px}@media(max-width:850px){.meeting-layout{grid-template-columns:1fr}}
</style>
